scenarios.representativeOutput:
export async function sendNotification(input, deps) {
  return deps.emailProvider.send({
    to: input.recipient,
    subject: input.subject,
    body: input.body,
  });
}

export function calculateTotal(baseAmount, rules) {
  const discounted = rules.applyDiscount(baseAmount);
  return rules.applyTax(discounted);
}

export async function processOrder(dto, deps) {
  const order = await deps.orders.findById(dto.orderId);
  await deps.account.charge(dto.amount);
  return { orderId: order.id, status: 'processed' };
}
